mapper.update:
UPDATE CART_ITEM CI

SET CI.QUANTITY = #{quantity}

WHERE CI.CART_ITEM_NO = #{cartItemNo}

  AND EXISTS (
      SELECT 1
      FROM CART C
      WHERE C.CART_NO = CI.CART_NO
        AND C.MEMBER_NO = #{memberNo}
  )

mapper.delete:
